svg.script:
// --- ÉTAT DE LA CAMÉRA 3D ---
let yaw = Math.PI / 4;
let pitch = Math.PI / 4;
let zoom = 1.0;
let camX = 400;
let camY = 300;

// --- PARAMÈTRES TERRAIN ---
let MAP_X = 32;
let MAP_Y = 32;
let TILE_SIZE = 18;
let Z_SCALE = 1.5;
let BRUSH_STRENGTH = 0.1; // Ultra doux pour un contrôle fin
let BRUSH_RADIUS = 2;
let LIGHT_MODE = 1;
let USE_SHADOW = true;
let USE_SLOPE_ROCK = true;
let USE_WATER = true;
let TERRAIN_TYPE = 0;
let BRUSH_SHAPE = 0;

// --- BRUIT DE PERLIN (fBm) ---
let perm = [];
function initNoise() {
for(let i=0; i<256; i++) perm[i] = Math.floor(Math.random()*256);
    perm = perm.concat(perm);
    }
    initNoise();
    function fade(t) { return t*t*t*(t*(t*6-15)+10); }
    function lerp(a, b, t) { return a + t*(b-a); }
    function hash(x, y) {
    let h = perm[(perm[x & 255] + (y & 255)) & 255];
    return h / 255;
    }
    function valNoise(x, y) {
    let xi = Math.floor(x), yi = Math.floor(y);
    let xf = x - xi, yf = y - yi;
    let u = fade(xf), v = fade(yf);
    let tl = hash(xi, yi), tr = hash(xi+1, yi);
    let bl = hash(xi, yi+1), br = hash(xi+1, yi+1);
    return lerp(lerp(tl, tr, u), lerp(bl, br, u), v);
    }
    function fBm(x, y, octaves=4, scale=0.1) {
    let total = 0, amp = 1, freq = scale, max = 0;
    for(let i=0; i<octaves; i++) {
        total += valNoise(x * freq, y * freq) * amp;
        max += amp;
        amp *= 0.5;
        freq *= 2;
        }
        return (total / max) * 2 - 1; // -1 à 1
        }

        // --- BIOMES (Échelle Réduite pour plus de nuances) ---
        const BIOMES = {
        "Saisonnier": { rockColor: '#5e5e5e', colors: [
        { h: -4, color: '#1a5f7a' }, { h: -1, color: '#2c87b0' }, { h: 0.5, color: '#d4a373' },
        { h: 2, color: '#588157' }, { h: 4, color: '#3a5a40' }, { h: 6, color: '#5e5e5e' }, { h: 8, color: '#ffffff' }
        ] },
        "Toundra": { rockColor: '#4a4a4a', colors: [
        { h: -4, color: '#2c3e50' }, { h: -1, color: '#5d6d7e' }, { h: 0.5, color: '#aeb6bf' },
        { h: 2, color: '#7f8c8d' }, { h: 5, color: '#bdc3c7' }, { h: 8, color: '#ffffff' }
        ] },
        "Méditerranéen": { rockColor: '#8d6e63', colors: [
        { h: -4, color: '#0d47a1' }, { h: -1, color: '#42a5f5' }, { h: 0.5, color: '#fff9c4' },
        { h: 2, color: '#9ccc65' }, { h: 4, color: '#689f38' }, { h: 6, color: '#8d6e63' }, { h: 8, color: '#eceff1' }
        ] },
        "Taïga": { rockColor: '#4e4e4e', colors: [
        { h: -4, color: '#1a237e' }, { h: -1, color: '#3949ab' }, { h: 0.5, color: '#bcaaa4' },
        { h: 2, color: '#558b2f' }, { h: 5, color: '#33691e' }, { h: 7, color: '#4e4e4e' }, { h: 9, color: '#ffffff' }
        ] },
        "Volcanique": { rockColor: '#1a1a1a', colors: [
        { h: -4, color: '#3e1f1f' }, { h: -1, color: '#8b3a3a' }, { h: 1, color: '#3e2723' },
        { h: 3, color: '#b71c1c' }, { h: 6, color: '#ff5722' }, { h: 8, color: '#ffeb3b' }
        ] },
        "Savane": { rockColor: '#8d6e63', colors: [
        { h: -4, color: '#1a5f7a' }, { h: -1, color: '#2c87b0' }, { h: 0.5, color: '#e9c46a' },
        { h: 3, color: '#d4a373' }, { h: 6, color: '#bc6c25' }, { h: 8, color: '#8d6e63' }
        ] }
        };
        let biomeNames = Object.keys(BIOMES);
        let currentBiomeIdx = 0;
        let currentBiome = JSON.parse(JSON.stringify(BIOMES[biomeNames[0]]));

        // --- ÉTAT INTERNE ---
        const svgNS = "http://www.w3.org/2000/svg";
        const terrainGroup = document.getElementById("terrain");
        const svgElement = document.documentElement;
        const uiText = document.getElementById("ui-text");
        const modal = document.getElementById("modal");
        const colorListG = document.getElementById("colorList");
        const nativeColorPicker = document.getElementById("nativeColorPicker");
        let editingColorIdx = -1;
        let heights = [];
        let cellPolys = [];
        let currentTool = 'raise';
        let isMouseDown = false;
        let isRotating = false;
        let isPanning = false;
        let startMouseX = 0, startMouseY = 0;
        let startYaw = 0, startPitch = 0, startCamX = 0, startCamY = 0;
        let needsFullUpdate = false;

        // --- MOTEUR 3D ---
        function project(x, y, z) {
        let X = x - MAP_X / 2;
        let Z = y - MAP_Y / 2;
        let Y = z;
        let x1 = X * Math.cos(yaw) - Z * Math.sin(yaw);
        let z1 = X * Math.sin(yaw) + Z * Math.cos(yaw);
        let y1 = Y;
        let x2 = x1;
        let y2 = y1 * Math.cos(pitch) + z1 * Math.sin(pitch);
        let z2 = -y1 * Math.sin(pitch) + z1 * Math.cos(pitch);
        return { x: x2 * TILE_SIZE * zoom + camX, y: -y2 * TILE_SIZE * zoom + camY, z: z2 };
        }

        // --- ÉCLAIRAGE & COULEURS ---
        function shadeColor(color, percent) {
        let R = parseInt(color.substring(1,3),16);
        let G = parseInt(color.substring(3,5),16);
        let B = parseInt(color.substring(5,7),16);
        R = Math.min(255, Math.max(0, Math.floor(R * percent)));
        G = Math.min(255, Math.max(0, Math.floor(G * percent)));
        B = Math.min(255, Math.max(0, Math.floor(B * percent)));
        return `#${R.toString(16).padStart(2,'0')}${G.toString(16).padStart(2,'0')}${B.toString(16).padStart(2,'0')}`;
        }

        function getBaseColor(h, slope) {
        if (USE_SLOPE_ROCK && slope < 0.7) return currentBiome.rockColor; // Seuil 0.7 (environ 45°)
            let colors = currentBiome.colors;
            let color = colors[0].color;
            for(let i=0; i<colors.length; i++) {
                if(h >= colors[i].h) color = colors[i].color;
                else break;
                }
                return color;
                }

                const Lx = 0.3, Ly = -0.5, Lz = -0.8;
                const Llen = Math.sqrt(Lx*Lx + Ly*Ly + Lz*Lz);
                const nLx = Lx/Llen, nLy = Ly/Llen, nLz = Lz/Llen;

                function getLitColor(x, y, type) {
                let h1 = heights[y][x], h2 = heights[y][x+1], h3 = heights[y+1][x+1], h4 = heights[y+1][x];
                let avgH, nx, ny, nz;
                if (type === 'A') { avgH = (h1 + h2 + h3) / 3; nx = (h1 - h2) * Z_SCALE; ny = (h2 - h3) * Z_SCALE; nz = 1; }
                else { avgH = (h1 + h3 + h4) / 3; nx = (h4 - h3) * Z_SCALE; ny = (h1 - h4) * Z_SCALE; nz = 1; }
                let nLen = Math.sqrt(nx*nx + ny*ny + nz*nz);
                let slope = nz / nLen;
                let baseColor = getBaseColor(avgH, slope);
                if (LIGHT_MODE === 0) return baseColor;
                nx /= nLen; ny /= nLen; nz /= nLen;
                let dot = nx * (-nLx) + ny * (-nLy) + nz * (-nLz);
                let intensity = 0.3 + Math.max(0, dot) * 0.7;
                if (LIGHT_MODE === 2) {
                if (intensity > 0.8) intensity = 1.0; else if (intensity > 0.5) intensity = 0.7; else if (intensity > 0.3) intensity = 0.4; else intensity = 0.2;
                } else if (LIGHT_MODE === 3) {
                let Rz = 2 * dot * nz - (-nLz);
                let spec = Math.pow(Math.max(0, Rz), 32);
                intensity += spec * 0.8;
                intensity = Math.min(1.5, intensity);
                }
                return shadeColor(baseColor, intensity);
                }

                // --- GÉNÉRATION TERRAIN (Hauteurs douces et nuancées) ---
                function generateTerrain(w, h) {
                MAP_X = w; MAP_Y = h;
                heights = [];
                TILE_SIZE = Math.min(24, 350 / Math.max(w, h));
                initNoise();

                let typeNames = ["Naturel", "Montagnes", "Collines", "Archipel"];
                uiText.textContent = "Génération en cours... Type: " + typeNames[TERRAIN_TYPE];

                setTimeout(() => {
                for(let y=0; y<=h; y++) {
                    heights[y] = [];
                    for(let x=0; x<=w; x++) {
                        let e = fBm(x, y, 4, 0.08);
                        let val = 0;
                        switch(TERRAIN_TYPE) {
                        case 0: val = e * 4; break; // Naturel : plage -4 à +4
                        case 1: val = e > 0 ? Math.pow(e, 1.5) * 8 : e * 2; break; // Montagnes : pics à 8
                        case 2: val = Math.pow(Math.abs(e), 1.5) * Math.sign(e) * 2; break; // Collines : très doux -2 à +2
                        case 3: val = e < -0.1 ? e * 4 : Math.pow(e, 2) * 8; break; // Archipel : océans à -4, îles à 8
                            }
                            heights[y][x] = val;
                            }
                            }
                            buildMesh();
                            uiText.textContent = "Outil: " + (currentTool === 'raise' ? 'Élever' : currentTool === 'lower' ? 'Creuser' : 'Caméra') + " | Type: " + typeNames[TERRAIN_TYPE];
                            }, 10);
                            }

                            // --- ÉROSION THERMIQUE ---
                            function applyThermalErosion(iterations = 30) {
                            const T = 0.3; // Talus réduit pour les petites collines
                            for(let k=0; k<iterations; k++) {
                                let newHeights = JSON.parse(JSON.stringify(heights));
                                for(let y=0; y<=MAP_Y; y++) {
                                    for(let x=0; x<=MAP_X; x++) {
                                        let h = heights[y][x];
                                        let neighbors = [];
                                        if(y>0) neighbors.push({x, y:y-1});
                                        if(y<MAP_Y) neighbors.push({x, y:y+1});
                                            if(x>0) neighbors.push({x:x-1, y});
                                            if(x<MAP_X) neighbors.push({x:x+1, y});
                                                neighbors.forEach(n => {
                                                let nh = heights[n.y][n.x];
                                                let diff = h - nh;
                                                if (diff > T) {
                                                let move = (diff - T) * 0.2;
                                                newHeights[y][x] -= move;
                                                newHeights[n.y][n.x] += move;
                                                }
                                                });
                                                }
                                                }
                                                heights = newHeights;
                                                }
                                                buildMesh();
                                                }

                                                // --- ÉROSION FLUVIALE ---
                                                function applyHydraulicErosion(droplets = 2000) {
                                                for(let i=0; i<droplets; i++) {
                                                    let x = Math.floor(Math.random() * MAP_X);
                                                    let y = Math.floor(Math.random() * MAP_Y);
                                                    let sediment = 0, vel = 1;
                                                    for(let step=0; step<40; step++) {
                                                        if(x<0 || x>MAP_X || y<0 || y>MAP_Y) break;
                                                                let h = heights[y][x];
                                                                let lowest = {x: x, y: y, h: h};
                                                                if(x < MAP_X) { let nh = heights[y][x+1]; if(nh < lowest.h) lowest = {x:x+1, y:y, h:nh}; }
                                                                        if(x > 0)    { let nh = heights[y][x-1]; if(nh < lowest.h) lowest = {x:x-1, y:y, h:nh}; }
                                                                            if(y < MAP_Y) { let nh = heights[y+1][x]; if(nh < lowest.h) lowest = {x:x, y:y+1, h:nh}; }
                                                                                    if(y > 0)    { let nh = heights[y-1][x]; if(nh < lowest.h) lowest = {x:x, y:y-1, h:nh}; }
                                                                                        if(lowest.x === x && lowest.y === y) { heights[y][x] += sediment * 0.5; break; }
                                                                                        let diff = h - lowest.h;
                                                                                        vel = vel * 0.9 + diff * 0.1;
                                                                                        let carryCapacity = vel * 0.2; // Capacité réduite pour s'adapter aux petites hauteurs
                                                                                        if (sediment > carryCapacity) {
                                                                                        let dep = (sediment - carryCapacity) * 0.5;
                                                                                        heights[y][x] += dep;
                                                                                        sediment -= dep;
                                                                                        } else {
                                                                                        let erode = Math.min((carryCapacity - sediment) * 0.2, diff * 0.2);
                                                                                        heights[y][x] -= erode;
                                                                                        sediment += erode;
                                                                                        }
                                                                                        x = lowest.x; y = lowest.y;
                                                                                        }
                                                                                        }
                                                                                        buildMesh();
                                                                                        }

                                                                                        // --- RENDU ---
                                                                                        function buildMesh() {
                                                                                        terrainGroup.innerHTML = '';
                                                                                        if (USE_SHADOW) terrainGroup.setAttribute('filter', 'url(#dropShadow)');
                                                                                        else terrainGroup.removeAttribute('filter');

                                                                                        cellPolys = [];
                                                                                        let cellsUnder = [], cellsOver = [];
                                                                                        for (let y = 0; y < MAP_Y; y++) {
                                                                                            cellPolys[y] = [];
                                                                                            for (let x = 0; x < MAP_X; x++) {
                                                                                                cellPolys[y][x] = {};
                                                                                                let avgH = (heights[y][x] + heights[y][x+1] + heights[y+1][x+1] + heights[y+1][x]) / 4;
                                                                                                if (avgH < 0) cellsUnder.push({ x, y }); else cellsOver.push({ x, y });
                                                                                                    }
                                                                                                    }
                                                                                                    sortCellsByDepth(cellsUnder);
                                                                                                    cellsUnder.forEach(cell => createCellMesh(cell.x, cell.y));
                                                                                                    if (USE_WATER) drawWaterPlane();
                                                                                                    sortCellsByDepth(cellsOver);
                                                                                                    cellsOver.forEach(cell => createCellMesh(cell.x, cell.y));

                                                                                                    updateParamUI();
                                                                                                    }

                                                                                                    function drawWaterPlane() {
                                                                                                    let p1 = project(0, 0, 0);
                                                                                                    let p2 = project(MAP_X, 0, 0);
                                                                                                    let p3 = project(MAP_X, MAP_Y, 0);
                                                                                                    let p4 = project(0, MAP_Y, 0);
                                                                                                    let waterPoly = document.createElementNS(svgNS, "polygon");
                                                                                                    waterPoly.setAttribute("points", `${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y} ${p4.x},${p4.y}`);
                                                                                                    waterPoly.setAttribute("fill", "rgba(44, 135, 176, 0.7)");
                                                                                                    waterPoly.setAttribute("stroke", "#2c87b0");
                                                                                                    waterPoly.setAttribute("stroke-width", "1");
                                                                                                    waterPoly.setAttribute("pointer-events", "none"); // Laisser passer les clics
                                                                                                    terrainGroup.appendChild(waterPoly);
                                                                                                    }

                                                                                                    function sortCellsByDepth(cells) {
                                                                                                    cells.sort((a, b) => {
                                                                                                    let cA = project(a.x + 0.5, a.y + 0.5, heights[a.y][a.x]);
                                                                                                    let cB = project(b.x + 0.5, b.y + 0.5, heights[b.y][b.x]);
                                                                                                    return cB.z - cA.z;
                                                                                                    });
                                                                                                    }

                                                                                                    function createCellMesh(x, y) {
                                                                                                    let p1 = project(x, y, heights[y][x]);
                                                                                                    let p2 = project(x + 1, y, heights[y][x + 1]);
                                                                                                    let p3 = project(x + 1, y + 1, heights[y + 1][x + 1]);
                                                                                                    let p4 = project(x, y + 1, heights[y + 1][x]);

                                                                                                    let polyA = document.createElementNS(svgNS, "polygon");
                                                                                                    polyA.setAttribute("points", `${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`);
                                                                                                    polyA.setAttribute("fill", getLitColor(x, y, 'A'));
                                                                                                    polyA.dataset.cellx = x; polyA.dataset.celly = y;
                                                                                                    terrainGroup.appendChild(polyA);

                                                                                                    let polyB = document.createElementNS(svgNS, "polygon");
                                                                                                    polyB.setAttribute("points", `${p1.x},${p1.y} ${p3.x},${p3.y} ${p4.x},${p4.y}`);
                                                                                                    polyB.setAttribute("fill", getLitColor(x, y, 'B'));
                                                                                                    polyB.dataset.cellx = x; polyB.dataset.celly = y;
                                                                                                    terrainGroup.appendChild(polyB);

                                                                                                    cellPolys[y][x] = { polyA, polyB };
                                                                                                    }

                                                                                                    function requestFullUpdate() {
                                                                                                    if (!needsFullUpdate) {
                                                                                                    needsFullUpdate = true;
                                                                                                    requestAnimationFrame(() => {
                                                                                                    buildMesh();
                                                                                                    needsFullUpdate = false;
                                                                                                    });
                                                                                                    }
                                                                                                    }

                                                                                                    function updateCellVisual(x, y) {
                                                                                                    if (x < 0 || x >= MAP_X || y < 0 || y >= MAP_Y) return;
                                                                                                            let cellData = cellPolys[y][x];
                                                                                                            if(!cellData.polyA) return;
                                                                                                            let p1 = project(x, y, heights[y][x]);
                                                                                                            let p2 = project(x + 1, y, heights[y][x + 1]);
                                                                                                            let p3 = project(x + 1, y + 1, heights[y + 1][x + 1]);
                                                                                                            let p4 = project(x, y + 1, heights[y + 1][x]);
                                                                                                            cellData.polyA.setAttribute("points", `${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`);
                                                                                                            cellData.polyA.setAttribute("fill", getLitColor(x, y, 'A'));
                                                                                                            cellData.polyB.setAttribute("points", `${p1.x},${p1.y} ${p3.x},${p3.y} ${p4.x},${p4.y}`);
                                                                                                            cellData.polyB.setAttribute("fill", getLitColor(x, y, 'B'));
                                                                                                            }

                                                                                                            // --- INTERACTION TERRAIN ---
                                                                                                            function getGridPosFromMouse(e) {
                                                                                                            let el = document.elementFromPoint(e.clientX, e.clientY);
                                                                                                            if (el && el.dataset && el.dataset.cellx !== undefined) return { x: parseInt(el.dataset.cellx), y: parseInt(el.dataset.celly) };
                                                                                                            return null;
                                                                                                            }

                                                                                                            function getBrushFalloff(dx, dy) {
                                                                                                            let dist = Math.sqrt(dx * dx + dy * dy);
                                                                                                            if (dist > BRUSH_RADIUS) return 0;
                                                                                                            let norm = dist / BRUSH_RADIUS;
                                                                                                            if (BRUSH_SHAPE === 0) return 1 - norm;
                                                                                                            if (BRUSH_SHAPE === 1) return norm < 0.6 ? 1 : 1 - (norm - 0.6) / 0.4;
                                                                                                                if (BRUSH_SHAPE === 2) {
                                                                                                                let localDy = -dx * Math.sin(yaw) + dy * Math.cos(yaw);
                                                                                                                let rNorm = Math.abs(localDy) / BRUSH_RADIUS;
                                                                                                                return rNorm < 1 ? 1 - rNorm : 0;
                                                                                                                    }
                                                                                                                    return 1 - norm;
                                                                                                                    }

                                                                                                                    function terraform(e) {
                                                                                                                    let gridPos = getGridPosFromMouse(e);
                                                                                                                    if (!gridPos) return;
                                                                                                                    let actionMode = (currentTool === 'raise') ? 1 : -1;
                                                                                                                    for (let dy = -BRUSH_RADIUS; dy <= BRUSH_RADIUS; dy++) {
                                                                                                                        for (let dx = -BRUSH_RADIUS; dx <= BRUSH_RADIUS; dx++) {
                                                                                                                            let falloff = getBrushFalloff(dx, dy);
                                                                                                                            if (falloff > 0) {
                                                                                                                            let tx = gridPos.x + dx, ty = gridPos.y + dy;
                                                                                                                            if (tx >= 0 && tx < MAP_X && ty >= 0 && ty < MAP_Y) {
                                                                                                                                    heights[ty][tx] += actionMode * BRUSH_STRENGTH * falloff;
                                                                                                                                    }
                                                                                                                                    }
                                                                                                                                    }
                                                                                                                                    }
                                                                                                                                    for (let dy = -BRUSH_RADIUS - 1; dy <= BRUSH_RADIUS + 1; dy++) {
                                                                                                                                        for (let dx = -BRUSH_RADIUS - 1; dx <= BRUSH_RADIUS + 1; dx++) {
                                                                                                                                            updateCellVisual(gridPos.x + dx - 1, gridPos.y + dy - 1);
                                                                                                                                            updateCellVisual(gridPos.x + dx, gridPos.y + dy);
                                                                                                                                            }
                                                                                                                                            }
                                                                                                                                            }

                                                                                                                                            // --- SAUVEGARDE SVG ---
                                                                                                                                            function saveSVG() {
                                                                                                                                            let shadowFilter = USE_SHADOW ? `    <filter id="dropShadow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur in="SourceAlpha" stdDeviation="8"/><feOffset dx="8" dy="12" result="offsetblur"/><feComponentTransfer><feFuncA type="linear" slope="0.6"/></feComponentTransfer><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>\n` : '';
                                                                                                                                            let groupAttr = USE_SHADOW ? ` filter="url(#dropShadow)"` : '';
                                                                                                                                            let svgString = `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600">\n`;
                                                                                                                                                if (USE_SHADOW) svgString += `  <defs>\n${shadowFilter}  </defs>\n`;
                                                                                                                                                svgString += `  <rect width="800" height="600" fill="#111122" />\n`;
                                                                                                                                                svgString += `  <g id="terrain"${groupAttr}>\n`;
                                                                                                                                                    let polys = terrainGroup.querySelectorAll('polygon');
                                                                                                                                                    polys.forEach(p => {
                                                                                                                                                    let pts = p.getAttribute('points');
                                                                                                                                                    let fill = p.getAttribute('fill');
                                                                                                                                                    svgString += `    <polygon points="${pts}" fill="${fill}" stroke="#1e1e2e" stroke-width="0.5" stroke-linejoin="round" />\n`;
                                                                                                                                                    });
                                                                                                                                                    svgString += `  </g>\n</svg>`;
                                                                                                                                            let blob = new Blob([svgString], { type: "image/svg+xml;charset=utf-8" });
                                                                                                                                            let url = URL.createObjectURL(blob);
                                                                                                                                            const xhtmlNS = "http://www.w3.org/1999/xhtml";
                                                                                                                                            let a = document.createElementNS(xhtmlNS, 'a');
                                                                                                                                            a.href = url; a.download = 'terrain_lowpoly.svg';
                                                                                                                                            document.documentElement.appendChild(a); a.click(); document.documentElement.removeChild(a);
                                                                                                                                            URL.revokeObjectURL(url);
                                                                                                                                            }

                                                                                                                                            // --- UI & PARAMÈTRES ---
                                                                                                                                            function setTool(toolName) {
                                                                                                                                            currentTool = toolName;
                                                                                                                                            document.getElementById('btn-raise').setAttribute('class', toolName === 'raise' ? 'tool-btn active' : 'tool-btn');
                                                                                                                                            document.getElementById('btn-lower').setAttribute('class', toolName === 'lower' ? 'tool-btn active' : 'tool-btn');
                                                                                                                                            document.getElementById('btn-rotate').setAttribute('class', toolName === 'rotate' ? 'tool-btn active' : 'tool-btn');
                                                                                                                                            uiText.textContent = "Outil: " + (toolName === 'raise' ? 'Élever' : toolName === 'lower' ? 'Creuser' : 'Caméra') + " | Clic Droit: Déplacer | Molette: Zoomer";
                                                                                                                                            }

                                                                                                                                            function updateParamUI() {
                                                                                                                                            document.getElementById('zVal').textContent = Z_SCALE.toFixed(1);
                                                                                                                                            document.getElementById('bVal').textContent = BRUSH_STRENGTH.toFixed(1);
                                                                                                                                            document.getElementById('rVal').textContent = BRUSH_RADIUS;
                                                                                                                                            document.getElementById('brushVal').textContent = ['Dôme', 'Plateau', 'Crête'][BRUSH_SHAPE];
                                                                                                                                            document.getElementById('xVal').textContent = MAP_X;
                                                                                                                                            document.getElementById('yVal').textContent = MAP_Y;
                                                                                                                                            document.getElementById('lightVal').textContent = ['Plat', 'Lambert', 'Toon', 'Phong'][LIGHT_MODE];
                                                                                                                                            document.getElementById('slopeVal').textContent = USE_SLOPE_ROCK ? 'Oui' : 'Non';
                                                                                                                                            document.getElementById('waterVal').textContent = USE_WATER ? 'Oui' : 'Non';
                                                                                                                                            document.getElementById('shadowVal').textContent = USE_SHADOW ? 'Oui' : 'Non';
                                                                                                                                            document.getElementById('palName').textContent = biomeNames[currentBiomeIdx];
                                                                                                                                            renderColorList();
                                                                                                                                            }

                                                                                                                                            function toggleModal() {
                                                                                                                                            modal.style.display = modal.style.display === 'none' ? 'inline' : 'none';
                                                                                                                                            updateParamUI();
                                                                                                                                            }

                                                                                                                                            // --- GESTION DES BIOMES ---
                                                                                                                                            function renderColorList() {
                                                                                                                                            colorListG.innerHTML = '';
                                                                                                                                            let yRock = -30;
                                                                                                                                            let swR = document.createElementNS(svgNS, "rect");
                                                                                                                                            swR.setAttribute("x", 0); swR.setAttribute("y", yRock); swR.setAttribute("width", 20); swR.setAttribute("height", 20); swR.setAttribute("fill", currentBiome.rockColor); swR.setAttribute("class", "color-swatch");
                                                                                                                                            swR.addEventListener("click", () => openColorPicker(-1)); colorListG.appendChild(swR);
                                                                                                                                            let txtR = document.createElementNS(svgNS, "text"); txtR.setAttribute("x", 40); txtR.setAttribute("y", yRock + 15); txtR.setAttribute("class", "param-label"); txtR.textContent = "Roche (Pente)"; colorListG.appendChild(txtR);

                                                                                                                                            currentBiome.colors.forEach((c, i) => {
                                                                                                                                            let y = i * 25;
                                                                                                                                            let sw = document.createElementNS(svgNS, "rect"); sw.setAttribute("x", 0); sw.setAttribute("y", y); sw.setAttribute("width", 20); sw.setAttribute("height", 20); sw.setAttribute("fill", c.color); sw.setAttribute("class", "color-swatch");
                                                                                                                                            sw.addEventListener("click", () => openColorPicker(i)); colorListG.appendChild(sw);
                                                                                                                                            let txt = document.createElementNS(svgNS, "text"); txt.setAttribute("x", 40); txt.setAttribute("y", y + 15); txt.setAttribute("class", "param-label"); txt.textContent = "Altitude: "; colorListG.appendChild(txt);
                                                                                                                                            let hMinus = document.createElementNS(svgNS, "rect"); hMinus.setAttribute("x", 100); hMinus.setAttribute("y", y); hMinus.setAttribute("width", 20); hMinus.setAttribute("height", 20); hMinus.setAttribute("class", "param-btn");
                                                                                                                                            hMinus.addEventListener("click", () => { currentBiome.colors[i].h = Math.max(-20, currentBiome.colors[i].h - 0.5); currentBiome.colors.sort((a,b)=>a.h-b.h); requestFullUpdate(); renderColorList(); }); colorListG.appendChild(hMinus);
                                                                                                                                            let hmTxt = document.createElementNS(svgNS, "text"); hmTxt.setAttribute("x", 110); hmTxt.setAttribute("y", y + 15); hmTxt.setAttribute("class", "param-label"); hmTxt.setAttribute("text-anchor", "middle"); hmTxt.textContent = "-"; colorListG.appendChild(hmTxt);
                                                                                                                                            let hVal = document.createElementNS(svgNS, "text"); hVal.setAttribute("x", 140); hVal.setAttribute("y", y + 15); hVal.setAttribute("class", "param-val"); hVal.textContent = c.h.toFixed(1); colorListG.appendChild(hVal);
                                                                                                                                            let hPlus = document.createElementNS(svgNS, "rect"); hPlus.setAttribute("x", 160); hPlus.setAttribute("y", y); hPlus.setAttribute("width", 20); hPlus.setAttribute("height", 20); hPlus.setAttribute("class", "param-btn");
                                                                                                                                            hPlus.addEventListener("click", () => { currentBiome.colors[i].h = Math.min(50, currentBiome.colors[i].h + 0.5); currentBiome.colors.sort((a,b)=>a.h-b.h); requestFullUpdate(); renderColorList(); }); colorListG.appendChild(hPlus);
                                                                                                                                            let hpTxt = document.createElementNS(svgNS, "text"); hpTxt.setAttribute("x", 170); hpTxt.setAttribute("y", y + 15); hpTxt.setAttribute("class", "param-label"); hpTxt.setAttribute("text-anchor", "middle"); hpTxt.textContent = "+"; colorListG.appendChild(hpTxt);
                                                                                                                                            let del = document.createElementNS(svgNS, "rect"); del.setAttribute("x", 200); del.setAttribute("y", y); del.setAttribute("width", 40); del.setAttribute("height", 20); del.setAttribute("class", "param-btn");
                                                                                                                                            del.addEventListener("click", () => { if(currentBiome.colors.length > 1) { currentBiome.colors.splice(i, 1); requestFullUpdate(); renderColorList(); } }); colorListG.appendChild(del);
                                                                                                                                            let dTxt = document.createElementNS(svgNS, "text"); dTxt.setAttribute("x", 220); dTxt.setAttribute("y", y + 15); dTxt.setAttribute("class", "param-label"); dTxt.setAttribute("text-anchor", "middle"); dTxt.textContent = "X"; colorListG.appendChild(dTxt);
                                                                                                                                            });
                                                                                                                                            }

                                                                                                                                            function openColorPicker(idx) {
                                                                                                                                            editingColorIdx = idx;
                                                                                                                                            nativeColorPicker.value = (idx === -1) ? currentBiome.rockColor : currentBiome.colors[idx].color;
                                                                                                                                            nativeColorPicker.click();
                                                                                                                                            }

                                                                                                                                            nativeColorPicker.addEventListener('input', (e) => {
                                                                                                                                            if (editingColorIdx === -1) currentBiome.rockColor = e.target.value;
                                                                                                                                            else if (editingColorIdx !== -1) currentBiome.colors[editingColorIdx].color = e.target.value;
                                                                                                                                            requestFullUpdate(); renderColorList();
                                                                                                                                            });

                                                                                                                                            // --- ÉVÉNEMENTS SOURIS ---
                                                                                                                                            svgElement.addEventListener('mousedown', (e) => {
                                                                                                                                            e.preventDefault();
                                                                                                                                            if (modal.style.display !== 'none') return;
                                                                                                                                            if (e.target.id.startsWith('btn-')) return;
                                                                                                                                            isMouseDown = true; startMouseX = e.clientX; startMouseY = e.clientY;
                                                                                                                                            if (e.button === 2) { isPanning = true; startCamX = camX; startCamY = camY; }
                                                                                                                                            else if (currentTool === 'rotate') { isRotating = true; startYaw = yaw; startPitch = pitch; }
                                                                                                                                            else { terraform(e); }
                                                                                                                                            });

                                                                                                                                            svgElement.addEventListener('mousemove', (e) => {
                                                                                                                                            if (!isMouseDown) return;
                                                                                                                                            if (isPanning) { camX = startCamX + (e.clientX - startMouseX); camY = startCamY + (e.clientY - startMouseY); requestFullUpdate(); }
                                                                                                                                            else if (isRotating) {
                                                                                                                                            let deltaX = e.clientX - startMouseX, deltaY = e.clientY - startMouseY;
                                                                                                                                            yaw = startYaw - deltaX * 0.01;
                                                                                                                                            pitch = Math.max(0.1, Math.min(Math.PI / 2 - 0.05, startPitch + deltaY * 0.01));
                                                                                                                                            requestFullUpdate();
                                                                                                                                            } else { terraform(e); }
                                                                                                                                            });

                                                                                                                                            window.addEventListener('mouseup', () => { isMouseDown = false; isRotating = false; isPanning = false; });

                                                                                                                                            svgElement.addEventListener('wheel', (e) => {
                                                                                                                                            if (modal.style.display !== 'none') return;
                                                                                                                                            e.preventDefault();
                                                                                                                                            let oldZoom = zoom;
                                                                                                                                            zoom *= (e.deltaY < 0) ? 1.1 : 0.9;
                                                                                                                                                zoom = Math.max(0.2, Math.min(5, zoom));
                                                                                                                                                let rect = svgElement.getBoundingClientRect();
                                                                                                                                                let mx = e.clientX - rect.left, my = e.clientY - rect.top;
                                                                                                                                                camX = mx - (mx - camX) * (zoom / oldZoom);
                                                                                                                                                camY = my - (my - camY) * (zoom / oldZoom);
                                                                                                                                                requestFullUpdate();
                                                                                                                                                }, { passive: false });

                                                                                                                                                svgElement.addEventListener('contextmenu', (e) => e.preventDefault());

                                                                                                                                                document.getElementById('btn-raise').addEventListener('click', () => setTool('raise'));
                                                                                                                                                document.getElementById('btn-lower').addEventListener('click', () => setTool('lower'));
                                                                                                                                                document.getElementById('btn-rotate').addEventListener('click', () => setTool('rotate'));
                                                                                                                                                document.getElementById('btn-generate').addEventListener('click', () => { TERRAIN_TYPE = (TERRAIN_TYPE + 1) % 4; generateTerrain(MAP_X, MAP_Y); });
                                                                                                                                                document.getElementById('btn-save').addEventListener('click', saveSVG);
                                                                                                                                                document.getElementById('btn-params').addEventListener('click', toggleModal);
                                                                                                                                                document.getElementById('closeBtn').addEventListener('click', toggleModal);

                                                                                                                                                document.getElementById('zPlus').addEventListener('click', () => { Z_SCALE = Math.min(5, Z_SCALE + 0.1); requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('zMinus').addEventListener('click', () => { Z_SCALE = Math.max(0.1, Z_SCALE - 0.1); requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('bPlus').addEventListener('click', () => { BRUSH_STRENGTH = Math.min(5, BRUSH_STRENGTH + 0.1); updateParamUI(); });
                                                                                                                                                document.getElementById('bMinus').addEventListener('click', () => { BRUSH_STRENGTH = Math.max(0.1, BRUSH_STRENGTH - 0.1); updateParamUI(); });
                                                                                                                                                document.getElementById('rPlus').addEventListener('click', () => { BRUSH_RADIUS = Math.min(10, BRUSH_RADIUS + 1); updateParamUI(); });
                                                                                                                                                document.getElementById('rMinus').addEventListener('click', () => { BRUSH_RADIUS = Math.max(1, BRUSH_RADIUS - 1); updateParamUI(); });
                                                                                                                                                document.getElementById('brushBtn').addEventListener('click', () => { BRUSH_SHAPE = (BRUSH_SHAPE + 1) % 3; updateParamUI(); });
                                                                                                                                                document.getElementById('xPlus').addEventListener('click', () => generateTerrain(MAP_X + 8, MAP_Y));
                                                                                                                                                document.getElementById('xMinus').addEventListener('click', () => generateTerrain(Math.max(8, MAP_X - 8), MAP_Y));
                                                                                                                                                document.getElementById('yPlus').addEventListener('click', () => generateTerrain(MAP_X, MAP_Y + 8));
                                                                                                                                                document.getElementById('yMinus').addEventListener('click', () => generateTerrain(MAP_X, Math.max(8, MAP_Y - 8)));

                                                                                                                                                document.getElementById('lightBtn').addEventListener('click', () => { LIGHT_MODE = (LIGHT_MODE + 1) % 4; requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('slopeBtn').addEventListener('click', () => { USE_SLOPE_ROCK = !USE_SLOPE_ROCK; requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('waterBtn').addEventListener('click', () => { USE_WATER = !USE_WATER; buildMesh(); });
                                                                                                                                                document.getElementById('shadowBtn').addEventListener('click', () => { USE_SHADOW = !USE_SHADOW; buildMesh(); });

                                                                                                                                                document.getElementById('erosionThermalBtn').addEventListener('click', () => applyThermalErosion(30));
                                                                                                                                                document.getElementById('erosionHydraulicBtn').addEventListener('click', () => applyHydraulicErosion(2000));

                                                                                                                                                document.getElementById('palNext').addEventListener('click', () => { currentBiomeIdx = (currentBiomeIdx + 1) % biomeNames.length; currentBiome = JSON.parse(JSON.stringify(BIOMES[biomeNames[currentBiomeIdx]])); requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('palPrev').addEventListener('click', () => { currentBiomeIdx = (currentBiomeIdx - 1 + biomeNames.length) % biomeNames.length; currentBiome = JSON.parse(JSON.stringify(BIOMES[biomeNames[currentBiomeIdx]])); requestFullUpdate(); updateParamUI(); });
                                                                                                                                                document.getElementById('addColor').addEventListener('click', () => { if(currentBiome.colors.length < 10) { currentBiome.colors.push({ h: currentBiome.colors[currentBiome.colors.length-1].h + 2, color: '#cccccc' }); currentBiome.colors.sort((a,b)=>a.h-b.h); requestFullUpdate(); renderColorList(); } });

                                                                                                                                                    generateTerrain(32, 32);
